193: function resolvePlayerAction(action) {
194:   if (state.battleOver || state.actionLock) return;
195: 
196:   const player = state.player;
197:   const enemy = state.enemy;
198:   state.actionLock = true;
199: 
200:   let playerLog = '';
201:   let enemyReply = null;
202: 
203:   switch (action) {
204:     case 'dash': {
205:       const chargeGain = 18 + player.chargeRate * 0.4;
206:       addCharge(player, chargeGain);
207:       const hit = 6 + player.power + Math.random() * 6;
208:       const enemyGuard = enemy.guard * (enemy.lastAction === 'guard' ? 1.25 : 1);
209:       const finalDamage = Math.max(4, hit - enemyGuard * 0.45);
210:       const defeated = commitDamage(enemy, finalDamage);
211:       triggerReaction(player, 'Bursting');
212:       playerLog = `<strong>${player.name}</strong> launches a dash for <strong>${finalDamage.toFixed(0)}</strong> damage and gains charge.`;
213:       if (defeated) {
214:         writeLog(playerLog);
215:         endBattle(true);
216:         return;
217:       }
218:       break;
219:     }
220: 
221:     case 'guard': {
222:       addCharge(player, 12 + player.chargeRate * 0.25);
223:       player.guard += 2;
224:       triggerReaction(player, 'Guarding');
225:       playerLog = `<strong>${player.name}</strong> sets a guard stance and stabilizes the lane.`;
226:       break;
227:     }
228: 
229:     case 'focus': {
230:       addCharge(player, 22 + player.chargeRate * 0.6);
231:       const heal = 8 + player.guard * 0.8;
232:       player.hp = clamp(player.hp + heal, 0, player.maxHp);
233:       triggerReaction(player, 'Focused');
234:       playerLog = `<strong>${player.name}</strong> focuses on rhythm and recovers <strong>${heal.toFixed(0)}</strong> HP.`;
235:       break;
236:     }
237: 
238:     case 'finisher': {
239:       const finisherDamage = player.charge >= 70 ? 26 + player.power * 1.6 : 9 + player.power * 0.8;
240:       const damage = player.charge >= 70 ? finisherDamage : finisherDamage * 0.7;
241:       const enemyGuard = enemy.guard * (enemy.lastAction === 'guard' ? 1.35 : 1);
242:       const finalDamage = Math.max(4, damage - enemyGuard * 0.3);
243:       const defeated = commitDamage(enemy, finalDamage);
244:       player.charge = clamp(player.charge - 45, 0, player.maxCharge);
245:       triggerReaction(player, player.charge >= 25 ? 'Finishing' : 'Unstable');
246:       playerLog = `<strong>${player.name}</strong> unleashes a finisher for <strong>${finalDamage.toFixed(0)}</strong> damage.`;
247:       if (defeated) {
248:         writeLog(playerLog);
249:         endBattle(true);
250:         return;
251:       }
252:       break;
253:     }
254: 
255:     case 'recover': {
256:       const recovered = 12 + player.guard * 0.9;
257:       player.hp = clamp(player.hp + recovered, 0, player.maxHp);
258:       addCharge(player, 10);
259:       triggerReaction(player, 'Recovering');
260:       playerLog = `<strong>${player.name}</strong> regains footing and recovers <strong>${recovered.toFixed(0)}</strong> HP.`;
261:       break;
262:     }
263: 
264:     default:
265:       state.actionLock = false;
266:       return;
267:   }
268: 
269:   player.lastAction = action;
270:   writeLog(playerLog);
271: 
272:   enemyReply = enemyTurn();
273: 
274:   setTimeout(() => {
275:     state.actionLock = false;
276:     updateHud();
277:     if (state.battleOver) return;
278:   }, 260);
279: }
