281: function enemyTurn() {
282:   const player = state.player;
283:   const enemy = state.enemy;
284:   const chosen = chooseEnemyAction();
285: 
286:   if (chosen === 'strike') {
287:     const hit = 7 + enemy.power + Math.random() * 5;
288:     const guardMitigation = player.guard * (player.lastAction === 'guard' ? 1.25 : 1);
289:     const finalDamage = Math.max(3, hit - guardMitigation * 0.5);
290:     const defeated = commitDamage(player, finalDamage);
291:     enemy.lastAction = 'strike';
292:     triggerReaction(enemy, 'Attacking');
293:     writeLog(`<strong>${enemy.name}</strong> counters with a strike for <strong>${finalDamage.toFixed(0)}</strong> damage.`);
294:     if (defeated) {
295:       endBattle(false);
296:       return;
297:     }
298:   }
299: 
300:   if (chosen === 'guard') {
301:     addCharge(enemy, 14 + enemy.chargeRate * 0.35);
302:     enemy.guard += 2;
303:     enemy.lastAction = 'guard';
304:     triggerReaction(enemy, 'Bracing');
305:     writeLog(`<strong>${enemy.name}</strong> braces and reduces incoming damage next turn.`);
306:   }
307: 
308:   if (chosen === 'charge') {
309:     const boost = 18 + enemy.chargeRate * 0.8;
310:     addCharge(enemy, boost);
311:     enemy.lastAction = 'charge';
312:     triggerReaction(enemy, 'Charging');
313:     writeLog(`<strong>${enemy.name}</strong> surges rhythm and gains <strong>${boost.toFixed(0)}</strong> charge.`);
314:   }
315: 
316:   if (chosen === 'heal') {
317:     const healAmount = 10 + enemy.guard * 0.7;
318:     enemy.hp = clamp(enemy.hp + healAmount, 0, enemy.maxHp);
319:     enemy.lastAction = 'heal';
320:     triggerReaction(enemy, 'Recovering');
321:     writeLog(`<strong>${enemy.name}</strong> slips back into form and recovers <strong>${healAmount.toFixed(0)}</strong> HP.`);
322:   }
323: 
324:   enemy.charge = clamp(enemy.charge + enemy.chargeRate * 0.2, 0, enemy.maxCharge);
325:   if (enemy.charge >= 80 && Math.random() < 0.7) {
326:     const burstDamage = 16 + enemy.power * 1.2;
327:     const playerGuard = player.guard * (player.lastAction === 'guard' ? 1.25 : 1);
328:     const final = Math.max(5, burstDamage - playerGuard * 0.45);
329:     const defeated = commitDamage(player, final);
330:     triggerReaction(enemy, 'Exploding');
331:     writeLog(`<strong>${enemy.name}</strong> bursts with a power spike for <strong>${final.toFixed(0)}</strong> damage.`);
332:     if (defeated) {
333:       endBattle(false);
334:     }
335:   }
336: 
337:   updateHud();
338: }
